static int p2d89_emit_quadrilaterals_rectangles(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 rect[]={-16384,-10240,16384,-10240,16384,10240,-16384,10240};static const p2d89_q14 chamfer[]={-12288,-16384,12288,-16384,16384,-12288,16384,12288,12288,16384,-12288,16384,-16384,12288,-16384,-12288};static const p2d89_q14 tab[]={-16384,-12288,4096,-12288,8192,-16384,14336,-16384,16384,-14336,16384,12288,-16384,12288};static const p2d89_q14 plane[]={-12288,-8192,12288,-8192,16384,8192,-16384,8192};static const p2d89_q14 wide[]={-16384,-6144,16384,-6144,16384,6144,-16384,6144};static const p2d89_q14 tall[]={-6144,-16384,6144,-16384,6144,16384,-6144,16384};if(id==P2D89_SHAPE_RECTANGLE||id==P2D89_SHAPE_HOLLOW_RECTANGLE)return p2d89_i_poly(rect,4U,1,p);if(id==P2D89_SHAPE_ROUNDED_RECTANGLE)return p2d89_i_rounded_rect(16384,10240,3072,p);if(id==P2D89_SHAPE_CHAMFER_RECT||id==P2D89_SHAPE_BEVEL_RECT)return p2d89_i_poly(chamfer,8U,1,p);if(id==P2D89_SHAPE_CAPSULE||id==P2D89_SHAPE_PILL)return p2d89_i_rounded_rect(16384,8192,8192,p);if(id==P2D89_SHAPE_TAB)return p2d89_i_poly(tab,7U,1,p);if(id==P2D89_SHAPE_PLANE)return p2d89_i_poly(plane,4U,1,p);if(id==P2D89_SHAPE_RECT_WIDE)return p2d89_i_poly(wide,4U,1,p);if(id==P2D89_SHAPE_RECT_TALL)return p2d89_i_poly(tall,4U,1,p);return 0;}
const P2D89_Submodule p2d89_submodule_quadrilaterals_rectangles = { { P2D89_MODULE_QUADRILATERALS, "quadrilaterals", "rectangles", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_quadrilaterals_rectangles };
